package com.ellenco.platform.auth;import jakarta.persistence.*;import java.time.LocalDateTime;@Entity@Table(name="password_reset_tokens")public class PasswordResetToken{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JoinColumn(name="user_id")private User user;@Column(nullable=false,unique=true,length=64)private String tokenHash;@Column(nullable=false)private LocalDateTime expiresAt;private LocalDateTime usedAt;@Column(nullable=false)private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTokenHash(){return tokenHash;}public void setTokenHash(String v){tokenHash=v;}public LocalDateTime getExpiresAt(){return expiresAt;}public void setExpiresAt(LocalDateTime v){expiresAt=v;}public LocalDateTime getUsedAt(){return usedAt;}public void setUsedAt(LocalDateTime v){usedAt=v;}}
